    "source": "architecture \"Your vocabulary. Your rules.\" {\n  description \"An inline profile defines meaning; the renderer supplies the drawing templates.\"\n  config {\n    id workshop\n    title \"A small custom framework\"\n    version \"1.0\"\n    defaultRelation uses\n    type actor {\n      template person\n      attribute owner { type string required true minLength 1 }\n    }\n    type product {\n      template application\n      accent \"#6366f1\"\n      attribute owner { required true }\n      attribute criticality { required true enum low, medium, high }\n      attribute replicas { type integer min 1 max 20 }\n    }\n    type record {\n      template database\n      attribute owner { required true }\n    }\n    type domain { template package contains actor, product, record }\n    relation uses { from actor to product style flow }\n    relation persists {\n      from product\n      to record\n      style access\n      outgoing { min 1 max 1 }\n      attribute encrypted { type boolean required true }\n    }\n    viewpoint landscape {\n      nodes actor, product, record, domain\n      relations uses, persists\n      requiredNodes actor, product, record\n      requiredRelations uses, persists\n    }\n    viewpoint data {\n      nodes product, record, domain\n      relations persists\n      requiredNodes product, record\n      requiredRelations persists\n    }\n  }\n  model {\n    actor customer \"Customer\" { owner \"Experience team\" }\n    domain commerce \"Commerce domain\" {\n      product portal \"Customer portal\" {\n        owner \"Commerce team\"\n        criticality high\n        replicas 3\n        technology \"Web application\"\n        description \"Try removing owner or using an invalid criticality.\"\n      }\n      record orders \"Order data\" {\n        owner \"Data team\"\n        technology \"PostgreSQL\"\n      }\n    }\n    relation visits customer -> portal \"Uses\"\n    relation writes portal -> orders \"Persists\" { type persists encrypted true }\n  }\n  view overview \"Custom framework\" {\n    viewpoint landscape\n    direction right\n    route visits { curve rounded }\n    route writes { curve rounded }\n  }\n  view data \"Data perspective\" {\n    viewpoint data\n    include portal, orders\n    style portal { template component }\n  }\n}\n"
