    "source": "architecture \"NAFv4 · Capability Taxonomy\" {\n    description \"C1 specialization taxonomy: the more specialized capability points to its parent.\"\n    config { profile naf41-uaf }\n    model {\n        Capability c_SAR \"SAR\"\n        Capability c_maritimeSAR \"Maritime SAR\"\n        Capability c_landSAR \"Land SAR\"\n        Capability c_highMountainsSAR \"High Mountains SAR\"\n        Capability c_highSeaMaritimeSAR \"High Sea Maritime SAR\"\n        Capability c_nearShoreMaritimeSAR \"Near-Shore Maritime SAR\"\n        relation c0 c_maritimeSAR -> c_SAR \"is a kind of\" { type CapabilityGeneralization }\n        relation c0.1 c_highSeaMaritimeSAR -> c_maritimeSAR \"is a kind of\" { type CapabilityGeneralization }\n        relation c0.2 c_nearShoreMaritimeSAR -> c_maritimeSAR \"is a kind of\" { type CapabilityGeneralization }\n        relation c1 c_landSAR -> c_SAR \"is a kind of\" { type CapabilityGeneralization }\n        relation c1.1 c_highMountainsSAR -> c_landSAR \"is a kind of\" { type CapabilityGeneralization }\n    }\n    view taxonomy \"C1 · Roots at the top\" {\n        viewpoint C1\n        diagram tree {\n            relations [CapabilityGeneralization]\n            orientation down\n            siblingGap 48\n            levelGap 100\n        }\n        style c_SAR { backgroundColor \"#e0ffc0\" opacity 1 showIcon false }\n        style c_maritimeSAR { backgroundColor \"#e0ffc0\" opacity 1 showIcon false }\n        style c_landSAR { backgroundColor \"#e0ffc0\" opacity 1 showIcon false }\n        style c_highMountainsSAR { backgroundColor \"#e0ffc0\" opacity 1 showIcon false }\n        style c_highSeaMaritimeSAR { backgroundColor \"#e0ffc0\" opacity 1 showIcon false }\n        style c_nearShoreMaritimeSAR { backgroundColor \"#e0ffc0\" opacity 1 showIcon false }\n    }\n    view horizontal \"C1 · Roots on the left\" {\n        viewpoint C1\n        diagram tree {\n            relations [CapabilityGeneralization]\n            orientation right\n            showLabels false\n            curve orthogonal\n        }\n    }\n}\n"
