    "id": "diagrams",
    "title": "Seven diagram renderers",
    "subtitle": "Behavior, matrices, maps & details",
    "source": "architecture \"Seven diagram renderers\" {\n  description \"One shared model: interactions, behavior, traceability, capability assessment, delivery, and class details.\"\n  config {\n    type item {\n      template component\n      attribute owner { type reference targets item }\n      attribute signature { type string }\n      attribute maturity { type number min 0 max 5 }\n      attribute parentCapability { type reference targets item }\n      attribute start { type string format date }\n      attribute end { type string format date }\n    }\n    relation link { style flow }\n    defaultRelation link\n  }\n  model {\n    item client \"Rescue operator\"\n    item api \"Coordination API\"\n    item store \"Mission store\"\n    relation request client -> api \"Create mission\"\n    relation save api -> store \"Persist mission\"\n    relation ack store -> api \"Mission ID\"\n    relation response api -> client \"Mission accepted\"\n    relation audit api -> api \"Record audit event\"\n\n    item ready \"Ready\"\n    item active \"Coordinating\"\n    item closed \"Closed\"\n    relation activate ready -> active \"Dispatch requested\"\n    relation finish active -> closed \"Rescue completed\"\n    relation retry active -> active \"Update position\"\n\n    item ops \"Operations team\"\n    item crew \"Rescue crew\"\n    item start \"Start\" { owner ops }\n    item assess \"Assess incident\" { owner ops }\n    item decision \"Deploy?\" { owner ops }\n    item dispatch \"Dispatch team\" { owner crew }\n    item cancel \"Close incident\" { owner ops }\n    item end \"End\" { owner crew }\n    relation begin start -> assess \"\"\n    relation evaluate assess -> decision \"\"\n    relation approved decision -> dispatch \"Approved\"\n    relation rejected decision -> cancel \"Rejected\"\n    relation complete dispatch -> end \"\"\n    relation cancelled cancel -> end \"\"\n\n    item rescue \"Search & Rescue\" { maturity 3 }\n    item maritime \"Maritime rescue\" { parentCapability rescue maturity 4 }\n    item airborne \"Airborne rescue\" { parentCapability rescue maturity 2 }\n    item tracking \"Tracking\" { maturity 5 }\n    item planning \"Mission planning\"\n    relation enables api -> rescue \"Enables\"\n    relation tracks store -> tracking \"Supports\"\n    relation plans api -> planning \"Supports\"\n\n    item phase1 \"Pilot deployment\" { start \"2026-01-01\" end \"2026-04-01\" }\n    item phase2 \"Fleet rollout\" { start \"2026-04-01\" end \"2026-10-01\" }\n    item milestone \"Operational readiness\" { start \"2026-10-01\" end \"2026-10-01\" }\n    relation rollout phase1 -> phase2 \"Precedes\"\n    relation operational phase2 -> milestone \"Delivers\"\n\n    item mission \"Mission\"\n    item repository \"Mission repository\"\n    item identifier \"id\" { owner mission signature \"id: UUID\" }\n    item status \"status\" { owner mission signature \"status: MissionStatus\" }\n    item launch \"launch\" { owner mission signature \"launch(): MissionId\" }\n    item target \"target\" { owner launch signature \"target: Location\" }\n    item allocate \"Allocate assets\" { owner mission }\n    item contract \"Mission access\" { owner repository signature \"IMissionStore\" }\n    item port \"Persistence\" { owner repository signature \"store: IMissionStore\" }\n    relation uses mission -> repository \"Uses\"\n  }\n  view interaction \"Sequence · Mission creation\" {\n    include client, api, store\n    diagram sequence {\n      participants [client, api, store]\n      messages [request, save, ack, audit, response]\n      returns [ack, response]\n      asyncMessages [audit]\n    }\n  }\n  view states \"State · Mission lifecycle\" {\n    include ready, active, closed\n    diagram state { initial ready finals [closed] }\n  }\n  view workflow \"Swimlanes · Rescue workflow\" {\n    include ops, crew, start, assess, decision, dispatch, cancel, end\n    diagram activity { lanes [ops, crew] laneAttribute owner initial start finals [end] decisions [decision] }\n  }\n  view mapping \"Matrix · Services to capabilities\" {\n    include api, store, rescue, tracking, planning\n    diagram matrix { rows [api, store] columns [rescue, tracking, planning] relations [link] }\n  }\n  view assessment \"Heatmap · Capability maturity\" {\n    include rescue, maritime, airborne, tracking, planning\n    diagram heatmap { valueAttribute maturity parentAttribute parentCapability min 0 max 5 }\n  }\n  view delivery \"Timeline · Deployment roadmap\" {\n    include phase1, phase2, milestone\n    diagram timeline { startAttribute start endAttribute end }\n  }\n  view details \"Class · Mission structure\" {\n    include mission, repository, identifier, status, launch, target, allocate, contract, port\n    diagram class {\n      attributes [identifier, status]\n      methods [launch]\n      functions [allocate]\n      interfaces [contract]\n      ports [port]\n      parameters [target]\n      ownerAttribute owner\n      signatureAttribute signature\n    }\n  }\n}\n"
