    "source": "{\n  \"architecture\": {\n    \"name\": \"JSON architecture\",\n    \"description\": \"One model, two views, the same rules as the text syntax.\",\n    \"config\": { \"views\": \"all\" },\n    \"model\": {\n      \"elements\": {\n        \"user\": { \"type\": \"person\", \"name\": \"User\" },\n        \"platform\": {\n          \"type\": \"package\",\n          \"name\": \"Platform\",\n          \"elements\": {\n            \"api\": { \"type\": \"service\", \"name\": \"API\", \"technology\": \"REST\" },\n            \"data\": { \"type\": \"database\", \"name\": \"Data\" }\n          }\n        }\n      },\n      \"relations\": {\n        \"calls\": { \"from\": \"user\", \"to\": \"api\", \"name\": \"Calls\" },\n        \"reads\": { \"from\": \"api\", \"to\": \"data\", \"name\": \"Reads\", \"type\": \"access\" }\n      }\n    },\n    \"views\": {\n      \"overview\": {\n        \"name\": \"Overview\",\n        \"direction\": \"right\",\n        \"place\": { \"user\": { \"at\": [0, 100] }, \"platform\": { \"at\": [350, 0] } },\n        \"style\": { \"api\": { \"iconPosition\": \"right\", \"showStereotype\": false } },\n        \"routes\": { \"curve\": \"straight\", \"icon\": \"core.cloud\", \"iconPosition\": \"top\" },\n        \"route\": { \"reads\": { \"showLabel\": false } }\n      },\n      \"matrix\": {\n        \"name\": \"Relationships\",\n        \"include\": [\"user\", \"api\", \"data\"],\n        \"diagram\": { \"type\": \"matrix\", \"rows\": [\"user\", \"api\"], \"columns\": [\"api\", \"data\"] }\n      }\n    }\n  }\n}\n"
